# This code has been fully generated by an AI.
"""Green-Screen-Memes aus einem ZIP freistellen und als Soundboard-Kacheln ablegen.

Bei beendeter App aufrufen: ``.venv\\Scripts\\python -m hebocon.memes Green-Screen-Memes.zip``
"""

import argparse
import tempfile
import zipfile
from concurrent.futures import ProcessPoolExecutor
from fractions import Fraction
from pathlib import Path

import av
import cv2
import numpy as np

from .server import MEDIA_DIR, MediaStore

VIDEO_EXT = (".mp4", ".mov", ".m4v", ".webm", ".mkv")
# Die Bühne zeigt Memes höchstens etwa ein Drittel so groß wie den Bildschirm; mehr kostet nur Dekodierzeit.
MAX_SIDE = 720
WORKERS = 3


def key_color(bgr: np.ndarray) -> np.ndarray:
    """Hintergrundgrün, gemessen am Bildrand; jedes Video hat ein anderes Grün."""
    border = np.concatenate([bgr[:8].reshape(-1, 3), bgr[-8:].reshape(-1, 3),
                             bgr[:, :8].reshape(-1, 3), bgr[:, -8:].reshape(-1, 3)])
    return np.median(border, axis=0).astype(np.float32)


def matte(bgr: np.ndarray, key: np.ndarray) -> np.ndarray:
    strength = max(1.0, float(key[1] - max(key[0], key[2])))
    px = bgr.astype(np.int16)
    excess = (px[..., 1] - np.maximum(px[..., 0], px[..., 2])).astype(np.float32)
    # Mischpixel an Kanten haben anteilig Grünüberschuss, daraus ergibt sich ein weicher Übergang.
    alpha = 1 - np.clip((excess - 0.2 * strength) / (0.6 * strength), 0, 1)
    alpha[alpha < 0.04] = 0
    alpha[alpha > 0.96] = 1
    return alpha


def cutout(bgr: np.ndarray, key: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Freigestellte Farben und Alpha; grüner Schimmer an Kanten wird neutralisiert."""
    alpha = matte(bgr, key)
    px = bgr.astype(np.float32)
    # Halbtransparente Kantenpixel enthalten anteilig Hintergrundgrün; herausgerechnet bleibt kein Saum.
    soft = (alpha > 0) & (alpha < 1)
    a = np.maximum(alpha[soft], 0.15)[:, None]
    px[soft] = np.clip((px[soft] - (1 - a) * key) / a, 0, 255)
    other = np.maximum(px[..., 0], px[..., 2])
    # Nur nahe der Kante entfärben, damit echtes Grün im Motiv (Kleidung, Logos) erhalten bleibt.
    edge = cv2.dilate((alpha < 0.99).astype(np.uint8), np.ones((7, 7), np.uint8)).astype(bool)
    px[..., 1] = np.where(edge, np.minimum(px[..., 1], other), px[..., 1])
    # Viele Quellen tragen einen hellen, nicht grünen Schein ums Motiv; daher die Kante leicht einziehen.
    alpha = cv2.GaussianBlur(cv2.erode(alpha, np.ones((3, 3), np.uint8), iterations=2), (3, 3), 0)
    alpha[alpha < 0.04] = 0
    px[alpha == 0] = 0
    return px, alpha


def content_box(src: Path, key: np.ndarray) -> tuple[int, int, int, int]:
    """Kleinstes Rechteck, in dem über das ganze Video etwas Sichtbares liegt."""
    seen = None
    with av.open(str(src)) as box:
        for i, frame in enumerate(box.decode(video=0)):
            if i % 3:
                continue
            small = cv2.resize(frame.to_ndarray(format="bgr24"), None, fx=0.25, fy=0.25,
                               interpolation=cv2.INTER_AREA)
            mask = matte(small, key) > 0.5
            seen = mask if seen is None else seen | mask
            h, w = frame.height, frame.width
    ys, xs = np.nonzero(seen)
    if not len(xs):
        return 0, 0, w, h
    pad = 12
    x0, y0 = max(0, xs.min() * 4 - pad), max(0, ys.min() * 4 - pad)
    x1, y1 = min(w, xs.max() * 4 + 4 + pad), min(h, ys.max() * 4 + 4 + pad)
    return int(x0), int(y0), int(x1), int(y1)


def convert(src: Path, dst: Path) -> None:
    """Grünes MP4 zu WebM (VP9 mit echtem Alphakanal, Ton als Opus)."""
    with av.open(str(src)) as probe:
        first = next(probe.decode(video=0)).to_ndarray(format="bgr24")
        fps = probe.streams.video[0].average_rate or Fraction(30)
    key = key_color(first)
    x0, y0, x1, y1 = content_box(src, key)
    scale = min(1.0, MAX_SIDE / max(x1 - x0, y1 - y0))
    # yuva420p braucht gerade Kantenlängen.
    width = max(2, round((x1 - x0) * scale / 2) * 2)
    height = max(2, round((y1 - y0) * scale / 2) * 2)

    with av.open(str(src)) as inp, av.open(str(dst), "w", format="webm") as out:
        vin = inp.streams.video[0]
        ain = inp.streams.audio[0] if inp.streams.audio else None
        vout = out.add_stream("libvpx-vp9", rate=fps)
        vout.width, vout.height, vout.pix_fmt = width, height, "yuva420p"
        vout.options = {"crf": "32", "b": "0", "deadline": "good", "cpu-used": "5", "row-mt": "1",
                        "tile-columns": "2", "auto-alt-ref": "0"}
        vout.thread_count = 4
        vout.metadata["alpha_mode"] = "1"
        aout = out.add_stream("libopus", rate=48000, layout="stereo") if ain else None
        index = 0
        for packet in inp.demux(*[s for s in (vin, ain) if s]):
            for frame in packet.decode():
                if packet.stream is vin:
                    # Erst verkleinern, dann freistellen: Mischpixel werden so zu weichen Kanten.
                    small = cv2.resize(frame.to_ndarray(format="bgr24")[y0:y1, x0:x1], (width, height),
                                       interpolation=cv2.INTER_AREA)
                    rgb, alpha = cutout(small, key)
                    bgra = np.dstack([rgb, alpha * 255]).round().astype(np.uint8)
                    out_frame = av.VideoFrame.from_ndarray(bgra, format="bgra").reformat(format="yuva420p")
                    out_frame.pts, out_frame.time_base = index, 1 / fps
                    index += 1
                    out.mux(vout.encode(out_frame))
                else:
                    frame.pts = None
                    out.mux(aout.encode(frame))
        out.mux(vout.encode(None))
        if aout:
            out.mux(aout.encode(None))


def main(argv: list[str] | None = None) -> None:
    parser = argparse.ArgumentParser(description="Green-Screen-Memes freistellen und ins Soundboard legen.")
    parser.add_argument("zip", type=Path, help="ZIP mit Green-Screen-Videos")
    parser.add_argument("--media", type=Path, default=MEDIA_DIR, help="Ablage des Soundboards")
    args = parser.parse_args(argv)

    store = MediaStore(args.media)
    known = {b.get("source") for b in store.board}
    with zipfile.ZipFile(args.zip) as pack, tempfile.TemporaryDirectory() as tmp:
        names = sorted(n for n in pack.namelist()
                       if n.lower().endswith(VIDEO_EXT) and Path(n).name not in known)
        if not names:
            print("Nichts zu tun: alle Videos aus dem ZIP liegen schon im Soundboard.")
            return
        jobs = []
        for name in names:
            src = Path(tmp) / Path(name).name
            src.write_bytes(pack.read(name))
            jobs.append((name, src, src.with_suffix(".webm")))
        done = {}
        with ProcessPoolExecutor(WORKERS) as pool:
            futures = {name: pool.submit(convert, src, dst) for name, src, dst in jobs}
            for (name, _, dst), future in zip(jobs, futures.values(), strict=True):
                try:
                    future.result()
                    done[name] = dst
                    print(f"[{len(done)}/{len(jobs)}] {Path(name).name} freigestellt")
                except Exception as exc:
                    # Ein kaputtes Video soll den Rest nicht aufhalten.
                    print(f"{Path(name).name}: übersprungen ({exc})")
        # Rückwärts einfügen, weil das Soundboard Neues vorne anzeigt; so steht Meme 001 oben.
        for name in reversed(names):
            if name in done:
                stem = Path(name).stem.replace("_", " ")
                store.add(done[name].read_bytes(), "video/webm", stem, board=True,
                          cutout=True, source=Path(name).name)
    print(f"{len(done)} Memes im Soundboard. App jetzt (neu) starten.")


if __name__ == "__main__":
    main()
